27	/**
28	 * Internal runtime object returned while a service instance is being assembled.
29	 *
30	 * It keeps the raw signal and `self` reference available for static building and store-backed
31	 * preloading, while callers typically consume the simpler `ServiceInstance` shape.
32	 */
33	export type ServiceRuntime<
34	  TState,
35	  TQueries extends Queries<TState>,
36	  TCommands extends Commands<TState>,
37	> = {
38	  stateSignal: ServiceSignal<TState>;
39	  selfRef: WritableSelf<TState>;
40	  queryCtx: QueryCtx<TState>;
41	  commands: ServiceInstance<TState, TQueries, TCommands>['commands'];
42	  queries: ServiceInstance<TState, TQueries, TCommands>['queries'];
43	};
