59	/**
60	 * Creates the mutable `self` object shared by runtime contexts.
61	 *
62	 * State writes are wrapped in an alien-signals batch so one command can update multiple fields
63	 * without causing unnecessary intermediate reactive notifications.
64	 */
65	function createSelfRef<TState>(stateSignal: ServiceSignal<TState>): WritableSelf<TState> {
66	  return {
67	    get state() {
68	      return stateSignal();
69	    },
70	    setState(mutate) {
71	      // Batch signal writes so one command only triggers subscribers after the full draft update.
72	      startBatch();
73	      try {
74	        stateSignal(produce(stateSignal(), mutate));
75	      } finally {
76	        endBatch();
77	      }
78	    },
79	    queries: {},
80	    commands: {},
81	  };
82	}
