84	/**
85	 * Builds the runtime command map from the declarative command definitions.
86	 *
87	 * Each runtime command validates raw caller input, invokes the handler with parsed values, and
88	 * validates the resolved output before returning it to the caller.
89	 */
90	function buildCommands<TState>(
91	  serviceId: string,
92	  commands: Commands<TState>,
93	  ctx: CommandCtx<TState>
94	): Command {
95	  return Object.fromEntries(
96	    Object.entries(commands).map(([name, def]) => {
97	      return [
98	        name,
99	        async (input: unknown) => {
100	          const validatedInput = await validateSchema(def.input, input, {
101	            kind: 'command',
102	            serviceId,
103	            name,
104	            phase: 'input',
105	          });
106	          const output = await def.handler(validatedInput, ctx);
107	
108	          return validateSchema(def.output, output, {
109	            kind: 'command',
110	            serviceId,
111	            name,
112	            phase: 'output',
113	          });
114	        },
115	      ];
116	    })
117	  );
118	}
