type RuntimeServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
type RuntimeQueryDefinition = QueryDefinition<unknown, AnySchema, AnySchema>;
type RegisteredServiceInstance = ServiceInstance<unknown, Queries<unknown>, Commands<unknown>>;

/**
 * Optional per-operation handler replacements applied when registering a service.
 *
 * Overrides are keyed by operation name and swap only the handler function, keeping each operation's
 * declared input/output schemas and other metadata intact. This is primarily useful for tests and
 * environment-specific wiring that needs to stub a single query or command.
 */
export type ServiceHandlerOverrides<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  queries?: Partial<{ [TKey in keyof TQueries]: TQueries[TKey]['handler'] }>;
  commands?: Partial<{ [TKey in keyof TCommands]: TCommands[TKey]['handler'] }>;
};

/** Compact overview of one registered service, safe to serialize for tooling and discovery. */
export type ServiceSummary = {
  id: string;
  description?: string;
  queryNames: string[];
  commandNames: string[];
};

/** Schema-referencing descriptor for one query or command operation. */
export type OperationDescriptor = {
  description?: string;
  input: AnySchema;
  output: AnySchema;
};

/** Full descriptor for one registered service, including schema references per operation. */
export type ServiceDescriptor = {
  id: string;
  description?: string;
  queries: Record<string, OperationDescriptor>;
  commands: Record<string, OperationDescriptor>;
};

type RegistryEntry = {
  definition: RuntimeServiceDefinition;
  instance: RegisteredServiceInstance;
};

/**
 * Process-wide registry of services keyed by id.
 *
 * The registry backs both runtime access (`getService`) and static builds, so handlers can look up
 * any other registered service by id while running normally or during static preload.
 */
const registry = new Map<string, RegistryEntry>();

/** Produces a new definition with the given operation handlers swapped in, if any are provided. */
function applyHandlerOverrides<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  overrides?: ServiceHandlerOverrides<TState, TQueries, TCommands>
): ServiceDefinition<TState, TQueries, TCommands> {
  if (!overrides || (!overrides.queries && !overrides.commands)) {
    return definition;
  }

  const queries = { ...definition.queries } as Queries<TState>;
  for (const [name, handler] of Object.entries(overrides.queries ?? {})) {
    const existing = queries[name];
    if (existing && handler) {
      queries[name] = { ...existing, handler: handler as (typeof existing)['handler'] };
    }
  }

  const commands = { ...definition.commands } as Commands<TState>;
  for (const [name, handler] of Object.entries(overrides.commands ?? {})) {
    const existing = commands[name];
    if (existing && handler) {
      commands[name] = { ...existing, handler: handler as (typeof existing)['handler'] };
    }
  }

  return {
    ...definition,
    queries: queries as TQueries,
    commands: commands as TCommands,
  };
}

/**
 * Registers a service definition into the global registry and returns its runtime instance.
 *
 * Optional handler overrides swap individual query/command handlers before the instance is built.
 * Registering the same id twice is treated as a programming error.
 */
export function registerService<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  overrides?: ServiceHandlerOverrides<TState, TQueries, TCommands>
): ServiceInstance<TState, TQueries, TCommands> {
  if (registry.has(definition.id)) {
    throw new OpenServiceAlreadyRegisteredError({ id: definition.id });
  }

  const effectiveDefinition = applyHandlerOverrides(definition, overrides);
  const instance = createService(effectiveDefinition);

  registry.set(definition.id, {
    definition: effectiveDefinition as RuntimeServiceDefinition,
    instance: instance as RegisteredServiceInstance,
  });

  return instance;
}

/** Removes every registered service from the global registry. */
export function clearRegistry(): void {
  registry.clear();
}

